.claude/settings.json:
{
  "hooks": {
    "SessionStart": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "command -v werkmeister >/dev/null 2>&1 && { werkmeister skills check >/dev/null 2>&1 || werkmeister skills sync >/dev/null 2>&1; werkmeister notes context; } || true"
          }
        ]
      },
      {
        "hooks": [
          {
            "type": "command",
            "command": "command -v werkmeister >/dev/null 2>&1 && werkmeister internal agent-state || true"
          }
        ]
      }
    ],
    "PreToolUse": [
      {
        "matcher": "Edit|Write",
        "hooks": [
          {
            "type": "command",
            "command": "command -v werkmeister >/dev/null 2>&1 && werkmeister internal gate || true"
          }
        ]
      },
      {
        "matcher": "Bash|mcp__.*create_pull_request",
        "hooks": [
          {
            "type": "command",
            "command": "command -v werkmeister >/dev/null 2>&1 && werkmeister internal pr-guard || true"
          }
        ]
      },
      {
        "hooks": [
          {
            "type": "command",
            "command": "command -v werkmeister >/dev/null 2>&1 && werkmeister internal agent-state || true"
          }
        ]
      }
    ],
    "UserPromptSubmit": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "command -v werkmeister >/dev/null 2>&1 && werkmeister internal agent-state || true"
          }
        ]
      }
    ],
    "PostToolUse": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "command -v werkmeister >/dev/null 2>&1 && werkmeister internal agent-state || true"
          }
        ]
      }
    ],
    "Notification": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "command -v werkmeister >/dev/null 2>&1 && werkmeister internal agent-state || true"
          }
        ]
      }
    ],
    "Stop": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "command -v werkmeister >/dev/null 2>&1 && werkmeister internal agent-state || true"
          }
        ]
      }
    ],
    "SessionEnd": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "command -v werkmeister >/dev/null 2>&1 && werkmeister internal agent-state || true"
          }
        ]
      }
    ]
  },
  "permissions": {
    "allow": [
      "Bash(git diff:*)",
      "Bash(git status:*)",
      "Bash(git ls-files:*)"
    ]
  }
}

.devcontainer/devcontainer.json:
// GENERATED by `werkmeister workspace init` (packages/werkmeister-core/src/devcontainer_gen.ts) — do not edit; rerun init-workspace.
{
  "name": "<WORKSPACE>",
  "image": "mcr.microsoft.com/devcontainers/javascript-node:22",
  "features": {
    "ghcr.io/devcontainers/features/github-cli:1": {}
  },
  "workspaceMount": "source=<ROOT>,target=<ROOT>,type=bind",
  "workspaceFolder": "<ROOT>",
  "mounts": [
    "source=<USERHOME>/workspace,target=<USERHOME>/workspace,type=bind",
    "source=features-claude-home-<WORKSPACE>,target=<USERHOME>/.claude,type=volume"
  ],
  "runArgs": [
    "--add-host=host.docker.internal:host-gateway"
  ],
  "containerEnv": {
    "HOME": "<USERHOME>",
    "GIT_CONFIG_COUNT": "1",
    "GIT_CONFIG_KEY_0": "safe.directory",
    "GIT_CONFIG_VALUE_0": "*"
  },
  "remoteUser": "node",
  "postCreateCommand": "sudo chown node:node \"$HOME\" \"$HOME/.claude\" && npm install -g @anthropic-ai/claude-code && (claude mcp remove --scope user werkmeister >/dev/null 2>&1 || true) && claude mcp add-json --scope user werkmeister '{\"type\":\"http\",\"url\":\"http://host.docker.internal:3002/mcp\",\"headersHelper\":\"printf '\\''{\\\"Authorization\\\":\\\"Bearer %s\\\"}'\\'' \\\"$(cat \\\"<ROOT>/.werkmeister/token\\\")\\\"\"}'"
}
